class Solution {
public:
    long long numberOfPairs(vector<int>& nums1, vector<int>& nums2, int k) {
        unordered_map<int, int> cnt1, cnt2;
        int max_val = 0;
        for (int x : nums1) {
            cnt1[x]++;
            if (x > max_val) max_val = x;
        }
        for (int y : nums2) cnt2[y]++;
        long long ans = 0;
        for (const auto& [val, c2] : cnt2) {
            long long step = 1LL * val * k;
            for (long long m = step; m <= max_val; m += step) {
                auto it = cnt1.find(m);
                if (it != cnt1.end()) {
                    ans += 1LL * c2 * it->second;
                }
            }
        }
        return ans;
    }
};

class Solution {
    public long numberOfPairs(int[] nums1, int[] nums2, int k) {
        Map<Integer, Integer> cnt1 = new HashMap<>();
        Map<Integer, Integer> cnt2 = new HashMap<>();
        int maxVal = 0;
        for (int x : nums1) {
            cnt1.put(x, cnt1.getOrDefault(x, 0) + 1);
            if (x > maxVal) maxVal = x;
        }
        for (int y : nums2) {
            cnt2.put(y, cnt2.getOrDefault(y, 0) + 1);
        }
        long ans = 0;
        for (Map.Entry<Integer, Integer> entry : cnt2.entrySet()) {
            int val = entry.getKey();
            int c2 = entry.getValue();
            long step = (long) val * k;
            for (long m = step; m <= maxVal; m += step) {
                if (cnt1.containsKey((int) m)) {
                    ans += (long) c2 * cnt1.get((int) m);
                }
            }
        }
        return ans;
    }
}

var numberOfPairs = function(nums1, nums2, k) {
    const cnt1 = new Map();
    const cnt2 = new Map();
    let maxVal = 0;
    for (const x of nums1) {
        cnt1.set(x, (cnt1.get(x) || 0) + 1);
        if (x > maxVal) maxVal = x;
    }
    for (const y of nums2) {
        cnt2.set(y, (cnt2.get(y) || 0) + 1);
    }
    let ans = 0;
    for (const [val, c2] of cnt2.entries()) {
        const step = val * k;
        for (let m = step; m <= maxVal; m += step) {
            if (cnt1.has(m)) {
                ans += c2 * cnt1.get(m);
            }
        }
    }
    return ans;
};
